export function reviewCounts(decisions) {
  const findings = reviewAreas.filter(area => area.finding);
  const reviewed = findings.filter(area => decisions[area.id]);
  return {
    total: findings.length,
    reviewed: reviewed.length,
    accepted: reviewed.filter(area => ['confirmed', 'corrected'].includes(decisions[area.id].status)).length,
    rejected: reviewed.filter(area => decisions[area.id].status === 'rejected').length,
  };
}
